import{_ as t,a as i,b as a,c as s,d as o}from"./chunks/en_m_prihlas_azure.BR14fm0d.js";import{_ as n,a as r}from"./chunks/m_qr_ios.BHk-vJJO.js";import{_ as l,o as c,c as p,aa as d}from"./chunks/framework.BAs_AphD.js";const v=JSON.parse('{"title":"First Steps with the Mobile App","description":"","frontmatter":{"title":"First Steps with the Mobile App","wiki":"en:diary:m_firststeps"},"headers":[],"relativePath":"en/diary/m_firststeps.md","filePath":"en/diary/m_firststeps.md","lastUpdated":1794388980000}'),g={name:"en/diary/m_firststeps.md"};function h(u,e,m,f,b,y){return c(),p("div",null,[...e[0]||(e[0]=[d('<h1 id="first-steps-with-the-mobile-app" tabindex="-1">First Steps with the Mobile App <a class="header-anchor" href="#first-steps-with-the-mobile-app" aria-label="Permalink to &quot;First Steps with the Mobile App&quot;">​</a></h1><figure class="shot" style="--w:200px;"><img src="'+t+'" alt="" width="180" data-no-zoom loading="lazy"></figure><p><strong>The Buildary.online mobile app is designed for creating and viewing Daily Records in the Project Diary, as well as creating and editing tickets.</strong> It will become a valuable assistant <strong>right on the project site</strong>.</p><p>Its purpose is not to replace the full range of functionality available in the Buildary.online web application.</p><p>We recommend using the mobile app only after your project and Project Diary(s) have been <strong>configured in the Buildary web application</strong>.</p><p><strong>THE OPERATIONS LISTED BELOW</strong>CANNOT** be performed using the mobile app. They must always be performed in the web application at <a href="http://www.buildary.online**:" target="_blank" rel="noreferrer">http://www.buildary.online**:</a></p><ul><li>creating a user account</li><li>creating and configuring a project, including drawings</li><li>adding project participants and Project Team Members, and configuring permissions</li><li>creating and configuring Project Diaries</li><li>defining rules for assigning ticket assignees and approvers</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>If you forget your login credentials</strong>, you also need to switch to the web interface. The login form there contains a link for resetting your forgotten password.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The app supports light and dark mode and automatically adapts to the phone&#39;s settings.</p></div><h2 id="getting-the-android-mobile-app" tabindex="-1">Getting the Android Mobile App <a class="header-anchor" href="#getting-the-android-mobile-app" aria-label="Permalink to &quot;Getting the Android Mobile App&quot;">​</a></h2><figure class="shot" style="--w:300px;"><img src="'+i+'" alt="" width="280" loading="lazy"></figure><figure class="shot" style="--w:150px;"><img src="'+n+'" alt="" width="120" loading="lazy"></figure><p><strong><strong>QR code for downloading the Android app</strong></strong></p><p>The <strong>app</strong> is available free of charge from the Google Play Store under the name <strong>Buildary.Online</strong>.</p><p>The mobile app is available for devices running <strong>Android 10.0 or later</strong>. If your device runs an incompatible version of Android, the app will not be displayed in the Google Play Store.</p><h2 id="getting-the-ios-mobile-app" tabindex="-1">Getting the iOS Mobile App <a class="header-anchor" href="#getting-the-ios-mobile-app" aria-label="Permalink to &quot;Getting the iOS Mobile App&quot;">​</a></h2><figure class="shot" style="--w:300px;"><img src="'+a+'" alt="" width="280" loading="lazy"></figure><figure class="shot" style="--w:150px;"><img src="'+r+'" alt="" width="120" loading="lazy"></figure><p><strong><strong>QR code for downloading the iOS app</strong></strong></p><p>The <strong>app</strong> is available free of charge from the App Store under the name <strong>Buildary Online</strong>.</p><p>The mobile app is available for devices running <strong>iOS 15 or later</strong>.</p><h2 id="logging-in-to-the-app" tabindex="-1">Logging in to the App <a class="header-anchor" href="#logging-in-to-the-app" aria-label="Permalink to &quot;Logging in to the App&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You need to log in to the app once every 30 days. On subsequent launches, the user is logged in automatically, provided they have remained signed in and have not logged out.</p></div><h3 id="_1-user-does-not-have-an-account" tabindex="-1">1/ User Does Not Have an Account <a class="header-anchor" href="#_1-user-does-not-have-an-account" aria-label="Permalink to &quot;1/ User Does Not Have an Account&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To create and activate an account, you need to use the web interface of the <a href="https://app.buildary.online/" target="_blank" rel="noreferrer">Buildary</a> application. The registration process is described in the <a href="/buildary-help-preview/en/firstofall/access">Access to the Program</a> chapter.</p></div><h3 id="_2-user-has-an-account-and-logs-in-using-email-and-password" tabindex="-1">2/ User Has an Account and Logs in Using Email and Password <a class="header-anchor" href="#_2-user-has-an-account-and-logs-in-using-email-and-password" aria-label="Permalink to &quot;2/ User Has an Account and Logs in Using Email and Password&quot;">​</a></h3><figure class="shot" style="--w:200px;"><img src="'+s+'" alt="" width="150" loading="lazy"></figure><ul><li>When the app is launched for the first time, the welcome screen with the <strong>Log in to the App</strong> button is displayed.</li><li>After pressing the button, the <strong>First Account</strong> login screen opens, where the user enters their <strong>login email and password</strong> and confirms them by selecting <strong>Log in</strong>.</li><li>After successful login, a list of projects the user has access to is displayed, allowing them to select the required project.</li><li>Each subsequent time the app is launched, the page corresponding to the user&#39;s last activity is displayed, either the last viewed Project Diary or the ticket list.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If incorrect login credentials are entered <strong>3 times consecutively</strong>, the account is <strong>temporarily locked/blocked</strong>. This lockout is time-limited, and the login credentials can be entered again after 10 minutes. If you do not remember your credentials, switch to the <strong>web interface</strong> and click <strong>Forgot password</strong> in the Buildary login form.</p></div><h3 id="_3-user-has-an-account-and-logs-in-using-azure-ad" tabindex="-1">3/ User Has an Account and Logs in Using Azure AD <a class="header-anchor" href="#_3-user-has-an-account-and-logs-in-using-azure-ad" aria-label="Permalink to &quot;3/ User Has an Account and Logs in Using Azure AD&quot;">​</a></h3><figure class="shot" style="--w:200px;"><img src="'+o+'" alt="" width="150" loading="lazy"></figure><ul><li>When the app is launched for the first time, the welcome screen with the <strong>Log in to the App</strong> button is displayed.</li><li>After pressing the button, the <strong>First Account</strong> login screen opens.</li><li>No information needs to be entered. Simply select <strong>Log in with Azure AD</strong>.</li><li>The user is logged in automatically. In some cases, they may be asked to enter their Microsoft account credentials.</li><li>After successful login, a list of projects the user has access to is displayed, allowing them to select the required project.</li><li>Each subsequent time the app is launched, the page corresponding to the user&#39;s last activity is displayed, either the last viewed Project Diary or the ticket list.</li></ul>',32)])])}const k=l(g,[["render",h]]);export{v as __pageData,k as default};
